import { gitmap } from '../data/githubContributions.js';
import { site } from '../data/site.js';

// Static GitHub contribution heatmap ("gitmap") for the About section.
// Data comes from src/data/githubContributions.js, generated by
// scripts/fetch-gitmap.mjs (`npm run gitmap`) — nothing runs at
// runtime, so it can never 403, rate-limit or fail offline.

const MONTH_ABBR = [
  'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
  'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec',
];
const MONTH_FULL = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December',
];
const WEEKDAY_LABELS = ['', 'Mon', '', 'Wed', '', 'Fri', ''];

// Decode once at module load — one pass over ~371 chars.
const DAY_MS = 86400000;
const startMs = Date.parse(`${gitmap.start}T00:00:00Z`);
const days = Array.from(gitmap.levels, (level, i) => {
  const date = new Date(startMs + i * DAY_MS);
  const iso = date.toISOString().slice(0, 10);
  return {
    iso,
    level: Number(level),
    // Exact count when known; undefined for an active day whose tip
    // didn't resolve (the title then says "Contributions", no number).
    count: gitmap.counts[iso],
    month: date.getUTCMonth(),
    dayOfMonth: date.getUTCDate(),
    year: date.getUTCFullYear(),
  };
});

// The graph starts on a Sunday (guarded in the fetch script), so a
// straight 7-char slice per column lines the rows up as Sun…Sat.
const weeks = [];
for (let i = 0; i < days.length; i += 7) weeks.push(days.slice(i, i + 7));

const activeDays = days.filter((d) => d.level > 0);
const total = activeDays.reduce((sum, d) => sum + (d.count || 0), 0);
const complete = activeDays.every((d) => d.count != null);
const first = days[0];
const last = days[days.length - 1];
const rangeLabel = `${MONTH_ABBR[first.month]} ${first.year} – ${MONTH_ABBR[last.month]} ${last.year}`;
const githubHref =
  site.socials.find((s) => s.label === 'GitHub')?.href || 'https://github.com/Harzolat';

// Today's cell (local date) gets a ring — but only while the data is
// fresh enough to still contain today; a stale snapshot shows no ring.
const now = new Date();
const todayIso = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

const cellTitle = (d) => {
  const on = `on ${MONTH_FULL[d.month]} ${d.dayOfMonth}, ${d.year}`;
  if (d.count != null) {
    return `${d.count} contribution${d.count === 1 ? '' : 's'} ${on}`;
  }
  return d.level > 0 ? `Contributions ${on}` : `No contributions ${on}`;
};

function Gitmap() {
  return (
    <div className="gitmap">
      <div className="gitmap-head">
        <p className="gitmap-title">GitHub activity</p>
        <p className="gitmap-meta">
          <span>
            {total}
            {complete ? '' : '+'} contributions · {rangeLabel}
          </span>
          <a href={githubHref} target="_blank" rel="noopener noreferrer">
            {githubHref.replace('https://', '')}{' '}
            <span aria-hidden="true">↗</span>
          </a>
        </p>
      </div>

      <div className="gitmap-body">
        <div className="gitmap-weekdays" aria-hidden="true">
          {WEEKDAY_LABELS.map((label, i) => (
            <span key={i}>{label}</span>
          ))}
        </div>

        <div className="gitmap-scroll">
          <div
            className="gitmap-grid"
            role="img"
            aria-label={`GitHub contribution map: ${total} contributions across ${activeDays.length} active days, ${rangeLabel}.`}
          >
            <div className="gitmap-months" aria-hidden="true">
              {weeks.map((week, i) => {
                const firstOfMonth = week.find((d) => d.dayOfMonth === 1);
                const show = i === 0 || firstOfMonth;
                const month = firstOfMonth ? firstOfMonth.month : week[0].month;
                return (
                  <span key={week[0].iso} className="gitmap-month">
                    {show ? MONTH_ABBR[month] : ''}
                  </span>
                );
              })}
            </div>
            <div className="gitmap-days" aria-hidden="true">
              {days.map((d) => (
                <span
                  key={d.iso}
                  className={`gm-cell lvl-${d.level}${d.iso === todayIso ? ' is-today' : ''}`}
                  title={cellTitle(d)}
                />
              ))}
            </div>
          </div>
        </div>
      </div>

      <div className="gitmap-legend" aria-hidden="true">
        <span>Less</span>
        {[0, 1, 2, 3, 4].map((lvl) => (
          <span key={lvl} className={`gm-cell lvl-${lvl}`} />
        ))}
        <span>More</span>
      </div>
    </div>
  );
}

export default Gitmap;
